def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    dangerous_prev = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 80.0:
                dangerous_prev.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b < 140.0 and b > moderate_prev:
            moderate_prev = b
    if moderate_prev == 0.0:
        moderate_prev = highest_prev

    alive_count = len(alive)
    expected_demand = WATER_REQ * (alive_count + 1)
    tight_supply = supply <= expected_demand
    very_tight = supply <= expected_demand - 4

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency <= 1:
        if highest_prev >= 150.0:
            bid = 12.0
        elif highest_prev >= 90.0:
            bid = 22.0
        else:
            bid = max(20.0, moderate_prev + 2.0)
    elif urgency == 2:
        if highest_prev >= 150.0:
            bid = 38.0
        else:
            bid = max(35.0, moderate_prev + 3.0)
    elif urgency == 3:
        if highest_prev >= 150.0:
            bid = 62.0
        else:
            bid = max(58.0, moderate_prev + 5.0)
    elif urgency == 4:
        if highest_prev >= 150.0:
            bid = 88.0
        else:
            bid = max(82.0, moderate_prev + 7.0)
    else:
        if highest_prev >= 150.0:
            bid = 118.0
        else:
            bid = max(105.0, moderate_prev + 10.0)

    if no_water_days >= 2 or hp <= 2:
        bid = max(bid, 120.0)
    elif no_water_days >= 1 and hp <= 4:
        bid = max(bid, 90.0)

    if supply >= 23 and urgency <= 2:
        bid *= 0.8
    elif supply <= 16:
        bid *= 1.12

    reserve_floor = 0.0
    if hp >= 7 and no_water_days == 0:
        reserve_floor = 10.0
    elif hp >= 5:
        reserve_floor = 5.0

    max_affordable = max(0.0, budget - reserve_floor)
    final_bid = min(bid, max_affordable)
    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Basic safety: if we are in trouble, bid to avoid further no-water days.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.45))

    # Read yesterday bids from previous_trace to infer aggressiveness.
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev['hp_after']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    lowest_prev_bid = min(prev_bids) if prev_bids else 0.0

    # Supply pressure: more supply reduces need to overbid.
    # Convert to an approximate "competition level".
    # If supply is near max, we can bid slightly less.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Determine target bid band.
    # Cindy's high bid suggests she will keep bidding aggressively; we try to beat her tier
    # only when our HP/no-water days require it.
    need_factor = 0.0
    if hp <= 2.0:
        need_factor = 1.0
    elif hp <= 4.0:
        need_factor = 0.75
    elif no_water_days >= 2:
        need_factor = 0.65
    elif no_water_days >= 1:
        need_factor = 0.45
    else:
        need_factor = 0.25

    # Base aggressiveness from yesterday.
    # If someone bid very high yesterday, we bid in the same order but scaled by need.
    # Otherwise, bid to slightly above the lower tier.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = highest_prev_bid * (0.78 + 0.22 * need_factor)
    else:
        # Not too extreme: anchor between lowest and a fraction of highest.
        anchor = lowest_prev_bid + 0.35 * (highest_prev_bid - lowest_prev_bid)
        target = anchor + (DAILY_SALARY * 0.18) * (0.5 + need_factor)

    # Adjust for supply: higher supply => reduce bid.
    target = target * (0.92 - 0.18 * supply_norm)

    # Budget constraints and floor.
    # Keep a minimum bid to stay competitive but never exceed budget.
    # Also avoid bidding more than a reasonable fraction of budget.
    cap = budget * 0.85 if budget > 0 else 0.0
    target = max(0.0, min(target, cap))

    # If our budget is tiny, bid whatever we can.
    if budget <= DAILY_SALARY * 0.15:
        return max(0.0, min(budget, DAILY_SALARY * 0.6))

    # Ensure bid is not trivially small when we need water.
    if need_factor >= 0.75:
        min_bid = DAILY_SALARY * 0.55
    elif need_factor >= 0.45:
        min_bid = DAILY_SALARY * 0.45
    else:
        min_bid = DAILY_SALARY * 0.30

    target = max(min_bid, target)
    target = min(target, budget)

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Urgency increases as the game progresses
    urgency_factor = 1.0 + (day_context['day'] / EPISODE_DAYS) * 0.3 

    # Base bid, adjusted by urgency
    base_bid = DAILY_SALARY * 0.6 * urgency_factor

    # Adjust bid based on my HP and no_water_days
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        # Critical HP or consecutive no water days, bid very aggressively
        bid = DAILY_SALARY * 0.95 * urgency_factor
    elif my_status['hp'] >= 8:
        # Healthy, can afford to be a bit less aggressive if competition isn't too high
        bid = DAILY_SALARY * 0.5 * urgency_factor
    else:
        bid = base_bid

    # Analyze yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If highest previous bid was significant, ensure we bid above it
        # Add a small increment to win against similar bids
        if highest_prev_bid >= DAILY_SALARY * 0.7: 
            bid = max(bid, highest_prev_bid + 5)
        else: 
            bid = max(bid, highest_prev_bid + 1)

    # Ensure bid is within budget
    final_bid = min(my_status['budget'], bid)

    # Ensure a minimum bid to secure water and signal presence
    if final_bid < DAILY_SALARY * 0.1:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    return final_bid
